-- =====================================================================
--  NextHappen — Datos DEMO para producción (Aiven MySQL)
--  Puebla usuarios y eventos de demostración. NO borra nada (INSERT IGNORE).
--  Las contraseñas están hasheadas con BCrypt (exportadas de un registro
--  real vía API), por lo que funcionan tal cual en producción.
--
--  Credenciales demo:
--    Organizador: organizador@nexthappen.demo  /  Demo1234!
--    Usuario:     usuario@nexthappen.demo       /  Demo1234!
--
--  Cómo ejecutarlo en Aiven (SSL obligatorio):
--    mysql --host <HOST> --port <PORT> --user avnadmin \
--          --password=<PASS> --ssl-mode=REQUIRED < seed-demo.sql
--
--  Requiere que el esquema ya exista (ver aiven-schema-update.sql).
--  Alternativa recomendada (más robusta): node scripts/seed-demo.mjs <URL-backend>
-- =====================================================================

SET NAMES utf8mb4;

